css:
.afl-root[data-afl-scope="s800e3039"]{margin-left:21px;color:windowtext;background-color:window;layout-grid:none}
.afl-root[data-afl-scope="s800e3039"] .xdListItem{display:inline-block;width:100%;vertical-align:text-top}
.afl-root[data-afl-scope="s800e3039"] .xdListBox,.afl-root[data-afl-scope="s800e3039"] .xdComboBox{margin:1px}
.afl-root[data-afl-scope="s800e3039"] .xdInlinePicture{margin:1px}
.afl-root[data-afl-scope="s800e3039"] .xdSection{border:1pt solid #FFFFFF;margin:6px 0px 6px 0px;padding:1px 1px 1px 5px}
.afl-root[data-afl-scope="s800e3039"] .xdRepeatingSection{border:1pt solid #FFFFFF;margin:6px 0px 6px 0px;padding:1px 1px 1px 5px}
.afl-root[data-afl-scope="s800e3039"] .xdRepeatingTable{BORDER-TOP-STYLE:none;BORDER-RIGHT-STYLE:none;BORDER-LEFT-STYLE:none;BORDER-BOTTOM-STYLE:none;BORDER-COLLAPSE:collapse;WORD-WRAP:break-word}
.afl-root[data-afl-scope="s800e3039"] .xdFileAttachment{display:inline-block;margin:1px}
.afl-root[data-afl-scope="s800e3039"] .xdTextBox{display:inline-block;white-space:nowrap;text-overflow:ellipsis;padding:1px;margin:1px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow:hidden;text-align:left}
.afl-root[data-afl-scope="s800e3039"] .xdRichTextBox{display:inline-block;padding:1px;margin:1px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow-x:hidden;word-wrap:break-word;text-overflow:ellipsis;text-align:left;font-weight:normal;font-style:normal;text-decoration:none;vertical-align:baseline}
.afl-root[data-afl-scope="s800e3039"] .xdDTPicker{display:inline;margin:1px;margin-bottom:2px;border:1pt solid #dcdcdc;color:windowtext;background-color:window;overflow:hidden;text-indent:0}
.afl-root[data-afl-scope="s800e3039"] .xdDTText{height:100%;width:100%;margin-right:22px;overflow:hidden;padding:0px;white-space:nowrap}
.afl-root[data-afl-scope="s800e3039"] .xdDTButton{margin-left:-21px;height:18px;width:20px}
.afl-root[data-afl-scope="s800e3039"] .xdRepeatingTable TD{VERTICAL-ALIGN:top}
.afl-root[data-afl-scope="s800e3039"]{FONT-FAMILY:Calibri, sans-serif;FONT-SIZE:10pt}
.afl-root[data-afl-scope="s800e3039"] TABLE{FONT-SIZE:10pt}
.afl-root[data-afl-scope="s800e3039"] h1{FONT-SIZE:16pt;COLOR:#17365d}
.afl-root[data-afl-scope="s800e3039"] h2{FONT-SIZE:12pt;COLOR:#365f91}
.afl-root[data-afl-scope="s800e3039"] TABLE.xdLayout TD{BORDER-TOP:medium none;BORDER-RIGHT:medium none;BORDER-BOTTOM:medium none;BORDER-LEFT:medium none}
.afl-root[data-afl-scope="s800e3039"] TABLE.msoUcTable TD{BORDER-TOP:1pt solid;BORDER-RIGHT:1pt solid;BORDER-BOTTOM:1pt solid;BORDER-LEFT:1pt solid}
.afl-root[data-afl-scope="s800e3039"]{FONT-SIZE:10pt;FONT-FAMILY:Calibri}
.afl-root[data-afl-scope="s800e3039"] SELECT{FONT-SIZE:10pt;FONT-FAMILY:Calibri}
.afl-root[data-afl-scope="s800e3039"] TABLE{FONT-SIZE:10pt;FONT-FAMILY:Calibri;TEXT-TRANSFORM:none;FONT-WEIGHT:normal;COLOR:black;FONT-STYLE:normal}
.afl-root[data-afl-scope="s800e3039"] .optionalPlaceholder{FONT-SIZE:9pt;TEXT-DECORATION:none;FONT-FAMILY:Calibri;FONT-WEIGHT:normal;COLOR:#333333;FONT-STYLE:normal}
.afl-root[data-afl-scope="s800e3039"] .langFont{FONT-SIZE:10pt;FONT-FAMILY:Calibri;WIDTH:150px}
.afl-root{contain:layout paint;position:relative}
:where(.afl-root .afl-required){position:relative}
.afl-root .afl-required::after,.afl-root .afl-required-mark{content:"*";position:absolute;right:3px;top:50%;width:8px;height:8px;margin-top:-4px;color:#FF0000;font:bold 12px/12px Arial,sans-serif;text-align:center;overflow:visible;pointer-events:none}
.afl-root .afl-required-mark{position:relative;display:inline-block;right:auto;top:auto;margin:0 0 0 -11px;vertical-align:middle}
:where(.afl-root [data-afl-ctrl]){min-height:1lh}
:where(.afl-root span[data-afl-ctrl]){display:inline-block}
.afl-root .afl-icon{display:inline-block;box-sizing:border-box;width:16px;height:16px;vertical-align:middle;flex:none}
.afl-root .afl-icon-calendar{border:1px solid #626f86;border-top-width:4px;border-radius:2px;background:#fff linear-gradient(#626f86,#626f86) 3px 3px/2px 2px repeat-x;background-clip:padding-box}
.afl-root .afl-icon-picture{width:48px;height:36px;border:1px dashed #8590a2;background:linear-gradient(135deg,transparent 55%,#c1c7d0 55%,#c1c7d0 70%,transparent 70%)}
.afl-root .afl-icon-signature{width:20px;border-bottom:2px solid #44546f;background:linear-gradient(150deg,transparent 45%,#44546f 45%,#44546f 55%,transparent 55%)}
.afl-root .afl-icon-unknown{border:1px dotted #8590a2}
.afl-root .afl-icon-file{width:12px;border:1px solid #626f86;border-radius:0 4px 0 0;background:#fff linear-gradient(#8590a2,#8590a2) 2px 5px/6px 1px no-repeat}
.afl-root .afl-attachment{display:inline-flex;align-items:center;gap:4px;white-space:nowrap;max-width:100%;overflow:hidden}.afl-root .afl-attachment-name{overflow:hidden;text-overflow:ellipsis}.afl-root .afl-attachment-size{color:#626f86}
.afl-root .afl-unsupported{box-sizing:border-box;min-height:24px;padding:4px 6px;border:1px solid #8590a2;background:#dcdfe4;color:#44546f;font:12px/16px sans-serif}
:where(.afl-root [nowrap]){white-space:nowrap}
.afl-root[data-afl-scope] div.xdDTPicker{display:inline-flex;align-items:center;box-sizing:border-box;max-width:calc(100% - 2px);vertical-align:middle}
.afl-root[data-afl-scope] .xdDTPicker .xdDTText{flex:1 1 auto;min-width:0;width:auto;margin-right:0}
.afl-root[data-afl-scope] .xdDTPicker .xdDTButton{flex:none;display:inline-flex;align-items:center;justify-content:center;margin:0;padding:0;border:0;background:none}
